def modified_caesar_cipher(text, shift):
  cipher_text = ""
  for char in text:
    if char.isalpha():
      if char.islower():
        ascii_offset = ord('a')
      else:
        ascii_offset = ord('A')
      cipher_char = chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
      cipher_text += cipher_char
    else:
      cipher_text += char
  return cipher_text

