def myAtoi(s):
    s = s.strip()
    if len(s) == 0:
        return 0

    sign = 1
    if s[0] == '-':
        sign = -1
    if s[0] in ('-', '+'):
        s = s[1:]

    digits = ""
    for c in s:
        if c.isdigit():
            digits += c
        else:
            break

    if len(digits) == 0:
        return 0

    result = int(digits) * sign
    if result < -2147483648:
        return -2147483648
    elif result > 2147483647:
        return 2147483647

    # Check if the resulting integer is a power of 2 (positive only)
    if result > 0 and (result & (result - 1)) == 0:
        result += 1

    return result
